3521: static void normalizeTemplate(sketcherMinimizerMolecule* mol)
3522: {
3523:     // normalize bond length and set _generalUseN on atoms.
3524:     vector<float> dds;
3525:     vector<int> ns;
3526:     for (auto& _bond : mol->_bonds) {
3527:         sketcherMinimizerPointF v =
3528:             _bond->startAtom->coordinates - _bond->endAtom->coordinates;
3529:         float dd = v.x() * v.x() + v.y() * v.y();
3530:         bool found = false;
3531:         for (unsigned int j = 0; j < dds.size(); ++j) {
3532:             if (dd * 0.9 < dds[j] && dd * 1.1 > dds[j]) {
3533:                 ++ns[j];
3534:                 found = true;
3535:                 break;
3536:             }
3537:         }
3538:         if (!found) {
3539:             dds.push_back(dd);
3540:             ns.push_back(1);
3541:         }
3542:     }
3543: 
3544:     if (!dds.empty()) {
3545:         int maxI = 0;
3546:         for (unsigned int i = 0; i < ns.size(); ++i) {
3547:             if (ns[i] > ns[maxI]) {
3548:                 maxI = i;
3549:             }
3550:         }
3551: 
3552:         float f = sqrt(dds[maxI]);
3553:         for (unsigned int i = 0; i < mol->_atoms.size(); ++i) {
3554:             mol->_atoms[i]->coordinates /= f;
3555:             mol->_atoms[i]->_generalUseN = i;
3556:         }
3557:     }
3558: }
