16: sketcherMinimizerMolecule* mol_from_mae_block(schrodinger::mae::Block& block)
17: {
18:     auto molecule = new sketcherMinimizerMolecule();
19:     // Atom data is in the m_atom indexed block
20:     {
21:         const auto atom_data =
22:             block.getIndexedBlock(schrodinger::mae::ATOM_BLOCK);
23:         // All atoms are gauranteed to have these three field names:
24:         const auto atomic_numbers =
25:             atom_data->getIntProperty(schrodinger::mae::ATOM_ATOMIC_NUM);
26:         const auto xs =
27:             atom_data->getRealProperty(schrodinger::mae::ATOM_X_COORD);
28:         const auto ys =
29:             atom_data->getRealProperty(schrodinger::mae::ATOM_Y_COORD);
30:         const auto size = atomic_numbers->size();
31: 
32:         // atomic numbers, and x, y, and z coordinates
33:         for (size_t i = 0; i < size; ++i) {
34:             auto atom = molecule->addNewAtom();
35:             atom->setAtomicNumber(atomic_numbers->at(i));
36:             atom->setCoordinates(sketcherMinimizerPointF(
37:                 static_cast<float>(xs->at(i)), static_cast<float>(ys->at(i))));
38:         }
39:     }
40: 
41:     // Bond data is in the m_bond indexed block
42:     try {
43:         const auto bond_data =
44:             block.getIndexedBlock(schrodinger::mae::BOND_BLOCK);
45:         // All bonds are gauranteed to have these three field names:
46:         auto from_atoms =
47:             bond_data->getIntProperty(schrodinger::mae::BOND_ATOM_1);
48:         auto to_atoms =
49:             bond_data->getIntProperty(schrodinger::mae::BOND_ATOM_2);
50:         auto orders = bond_data->getIntProperty(schrodinger::mae::BOND_ORDER);
51:         const auto size = from_atoms->size();
52: 
53:         for (size_t i = 0; i < size; ++i) {
54:             // Maestro atoms are 1 indexed!
55:             auto* from_atom = molecule->getAtoms().at(from_atoms->at(i) - 1);
56:             auto* to_atom = molecule->getAtoms().at(to_atoms->at(i) - 1);
57:             auto bond = molecule->addNewBond(from_atom, to_atom);
58:             bond->setBondOrder(orders->at(i));
59:         }
60:     } catch (const std::out_of_range&) {
61:         // no bonds.
62:     }
63: 
64:     return molecule;
65: }

