207: /* return true if the two segments intersect and if a result pointer was given,
208:  * set it to the intersection point */
209: struct sketcherMinimizerMaths {
210:     static bool
211:     intersectionOfSegments(const sketcherMinimizerPointF& s1p1,
212:                            const sketcherMinimizerPointF& s1p2,
213:                            const sketcherMinimizerPointF& s2p1,
214:                            const sketcherMinimizerPointF& s2p2,
215:                            sketcherMinimizerPointF* result = nullptr)
216:     {
217:         /*
218:                 Suppose the two line segments run from p to p + r and from q to
219:            q + s. Then any point on the first line is representable as p + t r
220:            (for a scalar parameter t) and any point on the second line as q + u
221:            s (for a scalar parameter u).
222: 
223:                 The two lines intersect if we can find t and u such that:
224: 
225:                     p + t r = q + u s
226: 
227:                         Cross both sides with s, getting
228: 
229:                         (p + t r) × s = (q + u s) × s
230: 
231:                         And since s × s = 0, this means
232: 
233:                         t (r × s) = (q − p) × s
234: 
235:                         And therefore, solving for t:
236: 
237:                             t = (q − p) × s / (r × s)
238: 
239:                             In the same way, we can solve for u:
240: 
241:                                 (p + t r) × r = (q + u s) × r
242: 
243:                                 u (s × r) = (p − q) × r
244: 
245:                                 u = (p − q) × r / (s × r)
246: 
247:                                 To reduce the number of computation steps, it's
248:            convenient to rewrite this as follows (remembering that s × r = − r ×
249:            s):
250: 
251:                                 u = (q − p) × r / (r × s)
252: 
253:                                 Now there are five cases:
254: 
255:                                 If r × s = 0 and (q − p) × r = 0, then the two
256:            lines are collinear. If in addition, either 0 ≤ (q − p) · r ≤ r · r
257:            or 0 ≤ (p − q) · s ≤ s · s, then the two lines are overlapping.
258: 
259:                                 If r × s = 0 and (q − p) × r = 0, but neither 0
260:            ≤ (q − p) · r ≤ r · r nor 0 ≤ (p − q) · s ≤ s · s, then the two lines
261:            are collinear but disjoint.
262: 
263:                                 If r × s = 0 and (q − p) × r ≠ 0, then the two
264:            lines are parallel and non-intersecting.
265: 
266:                                 If r × s ≠ 0 and 0 ≤ t ≤ 1 and 0 ≤ u ≤ 1, the
267:            two line segments meet at the point p + t r = q + u s.
268: 
269:                                 Otherwise, the two line segments are not
270:            parallel but do not intersect.
271:         */
272: 
273:         const sketcherMinimizerPointF& p = s1p1;
274:         sketcherMinimizerPointF r = s1p2 - s1p1;
275:         const sketcherMinimizerPointF& q = s2p1;
276:         sketcherMinimizerPointF s = s2p2 - s2p1;
277:         float rxs = crossProduct(r, s);
278:         if (rxs > -SKETCHER_EPSILON &&
279:             rxs < SKETCHER_EPSILON) { // parallel lines
280:             return false;
281:         }
282:         sketcherMinimizerPointF qminusp = q - p;
283:         float t = crossProduct(qminusp, s) / rxs;
284:         if (t < 0 || t > 1) {
285:             return false;
286:         }
287:         float u = crossProduct(qminusp, r) / rxs;
288:         if (u < 0 || u > 1) {
289:             return false;
290:         }
291:         if (result) {
292:             *result = p + t * r;
293:         }
294:         return true;
295:     }
