443:     static std::vector<float> tridiagonalSolve(const std::vector<float>& a,
444:                                                const std::vector<float>& b,
445:                                                const std::vector<float>& c,
446:                                                const std::vector<float>& rhs)
447:     {
448:         assert(a.size() == b.size() && a.size() == c.size() &&
449:                a.size() == rhs.size());
450:         assert(b[0] != 0.f);
451: 
452:         auto n = static_cast<unsigned int>(rhs.size());
453:         std::vector<float> u(n);
454:         std::vector<float> gam(n);
455: 
456:         float bet = b[0];
457:         u[0] = rhs[0] / bet;
458:         for (unsigned int j = 1; j < n; j++) {
459:             gam[j] = c[j - 1] / bet;
460:             bet = b[j] - a[j] * gam[j];
461:             assert(bet != 0.f);
462:             u[j] = (rhs[j] - a[j] * u[j - 1]) / bet;
463:         }
464:         for (unsigned int j = 1; j < n; j++) {
465:             u[n - j - 1] -= gam[n - j] * u[n - j];
466:         }
467: 
468:         return u;
469:     }
