471:     /* used by ClosedBezierControlPoints */
472:     static std::vector<float> cyclicSolve(const std::vector<float>& a,
473:                                           const std::vector<float>& b,
474:                                           const std::vector<float>& c,
475:                                           float alpha, float beta,
476:                                           const std::vector<float>& rhs)
477:     {
478:         assert(a.size() == b.size() && a.size() == c.size());
479:         auto n = static_cast<unsigned int>(b.size());
480:         assert(n > 2);
481:         float gamma = -b[0]; // Avoid subtraction error in forming bb[0].
482:         // Set up the diagonal of the modified tridiagonal system.
483:         std::vector<float> bb(n);
484:         bb[0] = b[0] - gamma;
485:         bb[n - 1] = b[n - 1] - alpha * beta / gamma;
486:         for (unsigned int i = 1; i < n - 1; i++) {
487:             bb[i] = b[i];
488:         }
489:         // Solve A · x = rhs.
490:         std::vector<float> solution = tridiagonalSolve(a, bb, c, rhs);
491:         std::vector<float> x = solution;
492: 
493:         // Set up the vector u.
494:         std::vector<float> u(n);
495:         u[0] = gamma;
496:         u[n - 1] = alpha;
497:         for (unsigned int i = 1; i < n - 1; i++) {
498:             u[i] = 0.f;
499:         }
500:         // Solve A · z = u.
501:         solution = tridiagonalSolve(a, bb, c, u);
502:         std::vector<float> z = solution;
503: 
504:         // Form v · x/(1 + v · z).
505:         double fact = (x[0] + beta * x[n - 1] / gamma) /
506:                       (1.f + z[0] + beta * z[n - 1] / gamma);
507: 
508:         // Now get the solution vector x.
509:         for (unsigned int i = 0; i < n; i++) {
510:             x[i] -= float(fact * z[i]);
511:         }
512:         return x;
513:     }
