515:     static sketcherMinimizerPointF
516:     pointOnCubicBezier(const sketcherMinimizerPointF& p1,
517:                        const sketcherMinimizerPointF& cp1,
518:                        const sketcherMinimizerPointF& cp2,
519:                        const sketcherMinimizerPointF& p2, float t)
520:     {
521:         // using Casteljiau's algorithm
522:         auto v1 = (1 - t) * p1 + t * cp1;
523:         auto v2 = (1 - t) * cp1 + t * cp2;
524:         auto v3 = (1 - t) * cp2 + t * p2;
525:         auto v4 = (1 - t) * v1 + t * v2;
526:         auto v5 = (1 - t) * v2 + t * v3;
527:         return (1 - t) * v4 + t * v5;
528:     }
