530:     /* find control points to a closed Bezier curve that passes through the
531:      * given points */
532:     static void ClosedBezierControlPoints(
533:         const std::vector<sketcherMinimizerPointF>& knots,
534:         std::vector<sketcherMinimizerPointF>& firstControlPoints,
535:         std::vector<sketcherMinimizerPointF>& secondControlPoints)
536:     {
537: 
538:         auto n = static_cast<unsigned int>(knots.size());
539:         if (n <= 2) {
540:             return;
541:         }
542: 
543:         // Calculate first Bezier control points
544: 
545:         std::vector<float> a(n), b(n), c(n);
546:         for (unsigned int i = 0; i < n; i++) {
547:             a[i] = 1;
548:             b[i] = 4;
549:             c[i] = 1;
550:         }
551: 
552:         std::vector<float> rhs(n);
553:         for (unsigned int i = 0; i < n; i++) {
554:             int j = i + 1;
555:             if (j > int(n - 1)) {
556:                 j = 0;
557:             }
558:             rhs[i] = 4 * knots[i].x() + 2 * knots[j].x();
559:         }
560:         // Solve the system for X.
561:         std::vector<float> x = cyclicSolve(a, b, c, 1, 1, rhs);
562: 
563:         for (unsigned int i = 0; i < n; i++) {
564:             int j = i + 1;
565:             if (j > int(n - 1)) {
566:                 j = 0;
567:             }
568:             rhs[i] = 4 * knots[i].y() + 2 * knots[j].y();
569:         }
570:         // Solve the system for Y.
571:         std::vector<float> y = cyclicSolve(a, b, c, 1, 1, rhs);
572: 
573:         // Fill output arrays.
574:         firstControlPoints.resize(n);
575:         secondControlPoints.resize(n);
576:         for (unsigned int i = 0; i < n; i++) {
577:             firstControlPoints[i] = sketcherMinimizerPointF(x[i], y[i]);
578:             secondControlPoints[i] = sketcherMinimizerPointF(
579:                 2 * knots[i].x() - x[i], 2 * knots[i].y() - y[i]);
580:         }
