613:     static float cannonBallDistance(float originX, float originY, float originZ,
614:                                     float directionX, float directionY,
615:                                     float directionZ, float targetX,
616:                                     float targetY, float targetZ, float ballR,
617:                                     float targetR, float cutOff = 4.f)
618:     // how far can a cannonball of radius ballR shot from origin travel befor
619:     // hitting a target ball of targetR radius
620:     {
621: 
622:         // assume that direction is normalized
623: 
624:         float targetdX = targetX - originX;
625:         float targetdY = targetY - originY;
626:         float targetdZ = targetZ - originZ;
627:         float rR = ballR + targetR;
628:         float d2 = (targetdX * targetdX) + (targetdY * targetdY) +
629:                    (targetdZ * targetdZ);
630: 
631:         if (d2 > (cutOff + rR) * (cutOff + rR)) {
632:             return cutOff;
633:         }
634: 
635:         if (d2 < rR * rR) {
636:             return 0;
637:         }
638: 
639:         float d = sqrt(d2);
640:         if (d > SKETCHER_EPSILON) {
641:             targetdX /= d;
642:             targetdY /= d;
643:             targetdZ /= d;
644:         }
645:         float cos = targetdX * directionX + targetdY * directionY +
646:                     targetdZ * directionZ;
647:         if (cos < 0) {
648:             return cutOff;
649:         }
650:         float sin = sqrt(1 - (cos * cos));
651:         float f = d * sin;
652:         if (f > rR) {
653:             return cutOff;
654:         }
655:         float result = sqrt(d2 - (f * f)) - sqrt((rR * rR) - (f * f));
656:         if (result > cutOff) {
657:             return cutOff;
658:         }
659:         return result;
660:     }
